func (v SpecValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	var bfd basetypes.ObjectValue

	if v.Bfd.IsNull() {
		bfd = types.ObjectNull(
			BfdValue{}.AttributeTypes(ctx),
		)
	}

	if v.Bfd.IsUnknown() {
		bfd = types.ObjectUnknown(
			BfdValue{}.AttributeTypes(ctx),
		)
	}

	if !v.Bfd.IsNull() && !v.Bfd.IsUnknown() {
		bfd = types.ObjectValueMust(
			BfdValue{}.AttributeTypes(ctx),
			v.Bfd.Attributes(),
		)
	}

	var level1 basetypes.ObjectValue

	if v.Level1.IsNull() {
		level1 = types.ObjectNull(
			Level1Value{}.AttributeTypes(ctx),
		)
	}

	if v.Level1.IsUnknown() {
		level1 = types.ObjectUnknown(
			Level1Value{}.AttributeTypes(ctx),
		)
	}

	if !v.Level1.IsNull() && !v.Level1.IsUnknown() {
		level1 = types.ObjectValueMust(
			Level1Value{}.AttributeTypes(ctx),
			v.Level1.Attributes(),
		)
	}

	var level2 basetypes.ObjectValue

	if v.Level2.IsNull() {
		level2 = types.ObjectNull(
			Level2Value{}.AttributeTypes(ctx),
		)
	}

	if v.Level2.IsUnknown() {
		level2 = types.ObjectUnknown(
			Level2Value{}.AttributeTypes(ctx),
		)
	}

	if !v.Level2.IsNull() && !v.Level2.IsUnknown() {
		level2 = types.ObjectValueMust(
			Level2Value{}.AttributeTypes(ctx),
			v.Level2.Attributes(),
		)
	}

	attributeTypes := map[string]attr.Type{
		"bfd": basetypes.ObjectType{
			AttrTypes: BfdValue{}.AttributeTypes(ctx),
		},
		"interface":      basetypes.StringType{},
		"interface_kind": basetypes.StringType{},
		"isis_instance":  basetypes.StringType{},
		"level":          basetypes.StringType{},
		"level1": basetypes.ObjectType{
			AttrTypes: Level1Value{}.AttributeTypes(ctx),
		},
		"level2": basetypes.ObjectType{
			AttrTypes: Level2Value{}.AttributeTypes(ctx),
		},
		"passive": basetypes.BoolType{},
		"type":    basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"bfd":            bfd,
			"interface":      v.Interface,
			"interface_kind": v.InterfaceKind,
			"isis_instance":  v.IsisInstance,
			"level":          v.Level,
			"level1":         level1,
			"level2":         level2,
			"passive":        v.Passive,
			"type":           v.SpecType,
		})

	return objVal, diags
}

func (v SpecValue) Equal(o attr.Value) bool {
	other, ok := o.(SpecValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Bfd.Equal(other.Bfd) {
		return false
	}

	if !v.Interface.Equal(other.Interface) {
		return false
	}

	if !v.InterfaceKind.Equal(other.InterfaceKind) {
		return false
	}

	if !v.IsisInstance.Equal(other.IsisInstance) {
		return false
	}

	if !v.Level.Equal(other.Level) {
		return false
	}

	if !v.Level1.Equal(other.Level1) {
		return false
	}

	if !v.Level2.Equal(other.Level2) {
		return false
	}

	if !v.Passive.Equal(other.Passive) {
		return false
	}

	if !v.SpecType.Equal(other.SpecType) {
		return false
	}

	return true
}

